const FOOTER="Pour vous donner une idée du format, voici un exemple d’interview que j’ai réalisée sur ma chaîne consacrée à l’Afrique :\n\nhttps://www.youtube.com/watch?v=z9B8b6ZrCb4";
// ENVOI AUTOMATIQUE (décision de Louis, 25-28/09) : toute fiche A_VERIFIER avec
// invitation conforme et un email candidat part sans validation. Plafond 8/jour.
const TRACKING_URL='https://n8n.nourmeet.com/webhook/impacteur-ouverture';
const PLAFOND_JOUR=8;
const lignes=$input.all().map(i=>i.json);
const _cfgRow=lignes.find(r=>String(r.cle_unique||'').trim()==='_config_telegram');
const chat_id=_cfgRow?String(_cfgRow.informations_a_verifier||'').trim():'';
const norm=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim();
const jourParis=t=>new Date(t).toLocaleDateString('fr-CA',{timeZone:'Europe/Paris'});
const publicDomains=new Set(['gmail.com','hotmail.com','outlook.com','yahoo.com','proton.me','icloud.com','live.com']);
const aujourdhui=jourParis(Date.now());
const envoyesAujourdhui=lignes.filter(r=>String(r.date_envoi||'').trim()&&jourParis(r.date_envoi)===aujourdhui).length;
let budget=PLAFOND_JOUR-envoyesAujourdhui;
if(budget<=0)return [];
const emailsInterdits=new Set(lignes.filter(r=>['NE_PAS_CONTACTER','REFUSE','OPPOSITION']
 .includes(String(r.statut||'').trim().toUpperCase()))
 .map(r=>String(r.email_contact||'').trim().toLowerCase()).filter(Boolean));
const emailsDejaServis=new Set(lignes.filter(r=>String(r.date_envoi||'').trim()||String(r.draft_id||'').trim())
 .map(r=>String(r.email_contact||'').trim().toLowerCase()).filter(Boolean));
const auteursDejaServis=new Set(lignes.filter(r=>String(r.date_envoi||'').trim()||String(r.draft_id||'').trim())
 .map(r=>norm(r.auteur)).filter(Boolean));
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
// GARDE-FOUS (19/10) : pas d'homonyme, jamais deux invitations à la même personne.
const MOTS_VIDES = new Set(['de', 'du', 'des', 'la', 'le', 'van', 'von', 'der', 'den', 'da', 'di', 'el', 'al', 'ben', 'ibn', 'bin', 'mc', 'st', 'saint']);

function normG(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ').trim();
}
function cleNom(nom) {
  return normG(nom).split(' ').filter(Boolean).sort().join(' ');
}
function emailNorm(e) {
  return String(e || '').trim().toLowerCase();
}

// L'adresse contient-elle le nom de la personne ?
function adresseCorrespond(auteur, email) {
  const e = emailNorm(email);
  const m = e.match(/^([^@]+)@(.+)$/);
  if (!m) return false;
  const local = normG(m[1]);                       // "nicolas dupont aignan"
  const localColle = local.replace(/ /g, '');     // "nicolasdupontaignan"
  const domaine = normG(m[2].replace(/\.[a-z]+$/, '')).replace(/ /g, ''); // "kotarac"
  const mots = normG(auteur).split(' ').filter(w => w.length > 1 && !MOTS_VIDES.has(w));
  if (mots.length < 2) return false;
  const prenom = mots[0];
  const nomFamille = mots.slice(1).join('');      // "dupontaignan", "legouriellec"
  // Site personnel : adresse@retiree.invalid
  if (nomFamille.length >= 4 && (domaine === nomFamille || domaine === prenom + nomFamille || (domaine.includes(nomFamille) && domaine.includes(prenom)))) return true;
  if (!localColle.includes(nomFamille)) {
    // nom composé : accepter si le dernier mot du nom est présent (ex. "le gouriellec")
    const dernier = mots[mots.length - 1];
    if (!(dernier.length >= 4 && local.split(' ').includes(dernier))) return false;
  }
  // Le nom est là. Le prénom doit être là, ou réduit à son initiale ; aucun autre prénom.
  const reste = localColle.replace(nomFamille, ' ').replace(mots[mots.length - 1], ' ');
  const autresMots = normG(reste).split(' ').filter(Boolean);
  if (local.split(' ').includes(prenom) || localColle.startsWith(prenom)) return true;
  if (autresMots.length === 1 && autresMots[0] === prenom[0]) return true; // "e.leclerc" pour Eric
  return false;                                                   // "bernard-dupont" pour Bertrand
}

const STATUTS_DEJA_INVITE=['ENVOYE','ENVOYE_MANUEL','BROUILLON_CREE'];
const dejaInvite=r=>String(r.date_envoi||'').trim()||String(r.draft_id||'').trim()||STATUTS_DEJA_INVITE.includes(String(r.statut||'').trim().toUpperCase());
for(const r of lignes)if(dejaInvite(r)){if(r.auteur)auteursDejaServis.add(cleNom(r.auteur));const e=String(r.email_contact||'').trim().toLowerCase();if(e)emailsDejaServis.add(e);}
const sortie=[];
const retenus=[];
for(const r of lignes){
 if(budget<=0)break;
 if(String(r.statut||'').trim().toUpperCase()!=='A_VERIFIER')continue;
 if(String(r.draft_id||'').trim()||String(r.date_envoi||'').trim())continue;
 if(!['Impacteur Afrique','Impacteur Frexit'].includes(String(r.chaine||'').trim()))continue;
 const objet=String(r.objet_auteur||'').trim();
 const message=String(r.message_auteur||'').trim();
 if(!objet||!message||!r.cle_unique)continue;
 if(!message.includes(FOOTER)||!message.endsWith('Cordialement,\nWalid\n'+String(r.chaine).trim())){retenus.push('👤 '+esc(String(r.auteur||'?'))+' ('+esc(String(r.chaine||'?'))+') — /valider '+String(r.cle_unique||''));continue;}
 if(auteursDejaServis.has(norm(r.auteur))||auteursDejaServis.has(cleNom(r.auteur)))continue;
 const nomFam=normG(r.auteur).split(' ').filter(w=>w.length>1).pop()||'';
 if(nomFam&&!normG(message).includes(nomFam))continue; // le message ne s'adresse pas à cette personne
 let candidats=[];try{candidats=JSON.parse(String(r.emails_candidats||'[]'));}catch(e){candidats=[];}
 if(!Array.isArray(candidats))candidats=[];
 // L'adresse écrite par louis dans la colonne email_contact passe en premier (11/10).
 const saisie=String(r.email_contact||'').trim().toLowerCase();
 // Sans saisie de louis, seule une adresse qui contient le nom de la personne peut partir (anti-homonymes).
 const okNom=candidats.filter(x=>x&&x.email&&adresseCorrespond(r.auteur,x.email));
 const best=saisie?{email:saisie,source:String(r.source_contact_validee||'')}:(okNom.find(x=>!publicDomains.has(String(x.email).split('@')[1]||''))||okNom[0]);
 if(!best)continue; // pas d'email -> louis l'ajoute dans la colonne email_contact du Sheet (ou /email via Telegram)
 const email=String(best.email).trim().toLowerCase();
 if(!/^\S+@\S+\.\S+$/.test(email)||emailsInterdits.has(email)||emailsDejaServis.has(email))continue;
 const pixel='<img src="'+TRACKING_URL+'?c='+encodeURIComponent(String(r.cle_unique))+'" width="1" height="1" alt="">';
 const message_html='<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#111">'
   +esc(message).replace(/\n/g,'<br>')+'</div>'+pixel;
 emailsDejaServis.add(email);auteursDejaServis.add(norm(r.auteur));auteursDejaServis.add(cleNom(r.auteur));
 sortie.push({json:{
  cle_unique:String(r.cle_unique),auteur:String(r.auteur||''),livre:String(r.livre||''),
  chaine:String(r.chaine).trim(),email_contact:email,objet,message_html,
  source_contact_validee:/^https:\/\//.test(String(best.source||''))?String(best.source):String(r.source_livre||''),
  chat_id
 },pairedItem:{item:0}});
 budget--;
}
if(retenus.length&&chat_id)sortie.push({json:{retenu:true,chat_id,telegram_message:'⚠️ '+retenus.length+' invitation(s) retenue(s) avant envoi : le texte ne correspond pas au modèle de la chaîne (signature ou exemple). Rien n\'est parti.\n'+retenus.join('\n')+'\n\nCorrige la fiche dans le Sheet, ou /valider CLE pour créer un brouillon à envoyer toi-même.'},pairedItem:{item:0}});
return sortie;

return $input.all().map((item,i)=>{
 const o=$('SELECTIONNER ENVOIS').itemMatching(i).json;
 if(!o.cle_unique)throw new Error('Fiche manquante après envoi.');
 return {json:{cle_unique:o.cle_unique,statut:'ENVOYE',
  corps:String(o.message_html||''),compte_envoi:'Gmail account',
  email_contact:o.email_contact,type_contact:'auteur',
  source_contact_validee:o.source_contact_validee,validation_contact:'OUI_AUTO',
  date_envoi:new Date().toISOString(),derniere_mise_a_jour:new Date().toISOString()},
  pairedItem:{item:i}};
});

return $input.all().map((item,i)=>{
 const o=$('SELECTIONNER ENVOIS').itemMatching(i).json;
 if(!o.cle_unique)throw new Error('Fiche manquante après envoi.');
 return {json:{cle_unique:o.cle_unique,statut:'ENVOYE',
  corps:String(o.message_html||''),compte_envoi:'Gmail - Impacteur Frexit',
  email_contact:o.email_contact,type_contact:'auteur',
  source_contact_validee:o.source_contact_validee,validation_contact:'OUI_AUTO',
  date_envoi:new Date().toISOString(),derniere_mise_a_jour:new Date().toISOString()},
  pairedItem:{item:i}};
});
